"""NPCI UPI AutoPay & Refund Webhook Handler (SEC-STD-02 compliant build)."""

from dataclasses import dataclass
import hashlib
import hmac
import re


@dataclass(frozen=True)
class WebhookResult:
    accepted: bool
    reason: str
    refund_id: str | None = None


_NON_DIGIT = re.compile(r"\D")


def _mask_vpa(vpa: str) -> str:
    """DPDP Act 2023 redaction: ra***@okicici. Never exposes the full local part."""
    text = str(vpa)
    if "@" in text:
        local, _, handle = text.rpartition("@")
    else:
        local, handle = text, ""
    prefix = local[:2] if len(local) > 2 else local[:1]
    masked = f"{prefix}***"
    if handle:
        return f"{masked}@{handle}"
    return masked


def _mask_mobile(mobile: str) -> str:
    """DPDP Act 2023 redaction: keep only the last 4 digits visible."""
    digits = _NON_DIGIT.sub("", str(mobile))
    if not digits:
        return "****"
    tail = digits[-4:]
    return ("*" * max(len(digits) - len(tail), 0)) + tail


class UpiWebhookProcessor:
    def __init__(self, webhook_secret: str, replay_window_seconds: int = 300) -> None:
        self.webhook_secret = webhook_secret
        self.replay_window_seconds = replay_window_seconds
        self.processed_events: set[str] = set()
        self.refund_ledger: list[dict[str, object]] = []
        self.audit_log: list[str] = []

    def _audit(
        self,
        outcome: str,
        event_id: str,
        timestamp: int,
        payer_vpa: str,
        mobile: str,
    ) -> None:
        self.audit_log.append(
            f"{outcome} event={event_id} vpa={_mask_vpa(payer_vpa)} "
            f"mobile={_mask_mobile(mobile)} ts={timestamp}"
        )

    @staticmethod
    def _normalize_signature(signature_header: str) -> str:
        provided = str(signature_header).strip()
        if provided[:7].lower() == "sha256=":
            provided = provided[7:]
        return provided.strip().lower()

    def verify_and_process(
        self,
        *,
        event_id: str,
        raw_body: str,
        signature_header: str,
        timestamp: int,
        now_ts: int,
        payer_vpa: str,
        mobile: str,
        amount_paise: int,
    ) -> WebhookResult:
        # 1. Symmetric replay window: rejects stale replays AND future-skewed forgeries.
        if abs(int(now_ts) - int(timestamp)) > self.replay_window_seconds:
            self._audit("rejected:STALE_OR_FUTURE_TIMESTAMP", event_id, timestamp, payer_vpa, mobile)
            return WebhookResult(accepted=False, reason="STALE_OR_FUTURE_TIMESTAMP", refund_id=None)

        # 2. Timestamp-bound HMAC-SHA256 over "{ts}.{body}", constant-time comparison (CWE-208).
        canonical = f"{int(timestamp)}.{raw_body}"
        expected = hmac.new(
            self.webhook_secret.encode("utf-8"),
            canonical.encode("utf-8"),
            hashlib.sha256,
        ).hexdigest()
        provided_hex = self._normalize_signature(signature_header)
        if (
            not provided_hex
            or not provided_hex.isascii()
            or not hmac.compare_digest(expected, provided_hex)
        ):
            self._audit("rejected:INVALID_SIGNATURE", event_id, timestamp, payer_vpa, mobile)
            return WebhookResult(accepted=False, reason="INVALID_SIGNATURE", refund_id=None)

        # 3. Positive paise guard before any state mutation.
        if int(amount_paise) <= 0:
            self._audit("rejected:INVALID_AMOUNT", event_id, timestamp, payer_vpa, mobile)
            return WebhookResult(accepted=False, reason="INVALID_AMOUNT", refund_id=None)

        # 4. event_id idempotency: empty or already-processed IDs never refund twice.
        if not event_id or event_id in self.processed_events:
            self._audit("rejected:DUPLICATE_EVENT_REPLAY", event_id, timestamp, payer_vpa, mobile)
            return WebhookResult(accepted=False, reason="DUPLICATE_EVENT_REPLAY", refund_id=None)

        # 5. Accept: mark processed, write redacted ledger row, return refund id.
        refund_id = f"REF-{event_id}"
        self.processed_events.add(event_id)
